class Solution {
public:
    int distinctSubseqII(string s) {
        const long long MOD = 1e9 + 7;
        long long dp = 1; // includes empty subsequence
        long long lastVal[26] = {};
        bool seen[26] = {};
        for (char ch : s) {
            int c = ch - 'a';
            long long prevDp = dp;
            long long newDp = (2 * dp) % MOD;
            if (seen[c]) {
                newDp = (newDp - lastVal[c] + MOD) % MOD;
            }
            lastVal[c] = prevDp;
            seen[c] = true;
            dp = newDp;
        }
        return (int)((dp - 1 + MOD) % MOD);
    }
};
